101: // --- POST /atividades ---
102: 
103: app.post('/atividades', (req, res) => {
104:   const { "x-usuario": usuario } = req.headers;
105:   if (!usuario) return res.status(401).json({ erro: 'USUARIO_DESCONHECIDO', mensagem: 'Usuário não informado' });
106: 
107:   // R1: DADOS_INVALIDOS
108:   if (!req.body || typeof req.body !== 'object') {
109:     return res.status(422).json({ erro: 'DADOS_INVALIDOS', mensagem: 'Corpo inválido' });
110:   }
111:   const { titulo, tipo, salaId, vagas, encontros } = req.body;
112:   if (!titulo || !tipo || !salaId || vagas === undefined || !encontros || !Array.isArray(encontros)) {
113:     return res.status(422).json({ erro: 'DADOS_INVALIDOS', mensagem: 'Campos obrigatórios ausentes ou de tipo errado' });
114:   }
115: 
116:   // R2: QUANTIDADE_DE_ENCONTROS
117:   if (tipo === 'palestra' && encontros.length !== 1) {
118:     return res.status(422).json({ erro: 'QUANTIDADE_DE_ENCONTROS', mensagem: 'Palestra deve ter exatamente 1 encontro' });
119:   }
120:   if (tipo === 'minicurso' && (encontros.length < 2 || encontros.length > 5)) {
121:     return res.status(422).json({ erro: 'QUANTIDADE_DE_ENCONTROS', mensagem: 'Minicurso deve ter entre 2 e 5 encontros' });
122:   }
123: 
124:   // R3: ENCONTRO_INVALIDO
125:   for (let i = 0; i < encontros.length; i++) {
126:     const e = encontros[i];
127:     if (new Date(e.inicio) >= new Date(e.fim)) {
128:       return res.status(422).json({ erro: 'ENCONTRO_INVALIDO', mensagem: 'Início deve ser menor que fim' });
129:     }
130:     const duracao = (new Date(e.fim) - new Date(e.inicio)) / 3600000;
131:     if (duracao <= 0 || duracao > 4) {
132:       return res.status(422).json({ erro: 'ENCONTRO_INVALIDO', mensagem: 'Duração fora do permitido' });
133:     }
134:     const dataInicio = e.inicio.split('T')[0];
135:     const dataFim = e.fim.split('T')[0];
136:     if (dataInicio !== dataFim) {
137:       return res.status(422).json({ erro: 'ENCONTRO_INVALIDO', mensagem: 'Encontro deve começar e terminar no mesmo dia' });
138:     }
139:     const dtInicio = new Date(e.inicio);
140:     const dtFim = new Date(e.fim);
141:     if (dtInicio < new Date('2026-10-19T00:00:00-03:00') || dtFim > new Date('2026-10-23T23:59:59-03:00')) {
142:       return res.status(422).json({ erro: 'ENCONTRO_INVALIDO', mensagem: 'Encontro fora do período do evento' });
143:     }
144:     for (let j = 0; j < encontros.length; j++) {
145:       if (i === j) continue;
146:       const outro = encontros[j];
147:       if (new Date(e.inicio).getTime() < new Date(outro.fim).getTime() && new Date(e.fim).getTime() > new Date(outro.inicio).getTime()) {
148:         return res.status(422).json({ erro: 'ENCONTRO_INVALIDO', mensagem: 'Encontros da mesma atividade não podem se sobrepor' });
149:       }
150:     }
151:   }
152: 
153:   // R4: VAGAS_ACIMA_DA_CAPACIDADE
154:   const sala = salas.find(s => s.id === salaId);
155:   if (!sala) return res.status(422).json({ erro: 'DADOS_INVALIDOS', mensagem: 'Sala não encontrada' });
156:   if (vagas > sala.capacidade || vagas < 1) {
157:     return res.status(422).json({ erro: 'VAGAS_ACIMA_DA_CAPACIDADE', mensagem: 'Vagas fora do permitido' });
158:   }
159: 
160:   // R5: CONFLITO_DE_SALA
161:   // Na mesma sala, entre o fim de um encontro e o início do seguinte deve haver no mínimo 15 minutos
162:   for (let i = 0; i < encontros.length; i++) {
163:     const e = encontros[i];
164:     for (const atvAtiva of atividades) {
165:       if (atvAtiva.salaId !== salaId) continue;
166:       for (let j = 0; j < atvAtiva.encontros.length; j++) {
167:         const ee = atvAtiva.encontros[j];
168:         if (calcularSituacao(atvAtiva) === 'cancelada') continue;
169:         // Verifica sobreposicao real usando timestamps
170:         if (new Date(e.inicio).getTime() < new Date(ee.fim).getTime() && new Date(e.fim).getTime() > new Date(ee.inicio).getTime()) {
171:           return res.status(409).json({ erro: 'CONFLITO_DE_SALA', mensagem: 'Conflito de sala: sobreposicao de horarios' });
172:         }
173:         // Calcula o gap entre os encontros (em minutos)
174:         const gap1 = (new Date(e.inicio).getTime() - new Date(ee.fim).getTime()) / 60000;
175:         const gap2 = (new Date(ee.inicio).getTime() - new Date(e.fim).getTime()) / 60000;
176:         if ((gap1 >= 0 && gap1 < 15) || (gap2 >= 0 && gap2 < 15)) {
177:           return res.status(409).json({ erro: 'CONFLITO_DE_SALA', mensagem: 'Conflito de sala: menos de 15 minutos de intervalo' });
178:         }
179:       }
180:     }
181:   }
182: 
183:   // Criar atividade
184:   const atividade = {
185:     id: `atv_${String(proximoId++).padStart(8, '0')}`,
186:     titulo,
187:     tipo,
188:     salaId,
189:     vagas,
190:     encontros: encontros.map(e => ({
191:       id: `enc_${String(Math.floor(Math.random() * 0xFFFFFFFF)).toString(16).padStart(8, '0')}`,
192:       inicio: e.inicio,
193:       fim: e.fim
194:     })),
195:     cargaHorariaMinutos: encontros.reduce((acc, e) => acc + (new Date(e.fim) - new Date(e.inicio)) / 60000, 0),
196:     ocupadas: req.body.ocupadas || 0,
197:     vagasRestantes: vagas,
198:     emEspera: 0
199:   };
200: 
201:   atividades.push(atividade);
202:   res.status(201).json(atividadeResponse(atividade));
203: });
204: 
205: // --- PATCH /atividades/:id ---
206: 
207: app.patch('/atividades/:id', (req, res) => {
208:   const { "x-usuario": usuario } = req.headers;
209:   if (!usuario) return res.status(401).json({ erro: 'USUARIO_DESCONHECIDO', mensagem: 'Usuário não informado' });
210: 
211:   const atv = atividades.find(a => a.id === req.params.id);
212:   if (!atv) return res.status(404).json({ erro: 'NAO_ENCONTRADO', mensagem: 'Atividade não encontrada' });
213: 
214:   const camposImutaveis = ['id', 'tipo'];
215:   const camposAlterados = Object.keys(req.body);
216: 
217:   // R6: CAMPO_NAO_EDITAVEL (id e tipo são imutáveis)
218:   const campoProibido = camposAlterados.find(c => camposImutaveis.includes(c));
219:   if (campoProibido) {
220:     return res.status(422).json({ erro: 'CAMPO_NAO_EDITAVEL', mensagem: `Campo ${campoProibido} não pode ser alterado` });
221:   }
222: 
223:   const novosEncontros = req.body.encontros;
224:   const novaSalaId = req.body.salaId;
225:   const novasVagas = req.body.vagas;
226: 
227:   // R7: QUANTIDADE_DE_ENCONTROS (se encontros alterados)
228:   if (novosEncontros) {
229:     if (atv.tipo === 'palestra' && novosEncontros.length !== 1) {
230:       return res.status(422).json({ erro: 'QUANTIDADE_DE_ENCONTROS', mensagem: 'Palestra deve ter exatamente 1 encontro' });
231:     }
232:     if (atv.tipo === 'minicurso' && (novosEncontros.length < 2 || novosEncontros.length > 5)) {
233:       return res.status(422).json({ erro: 'QUANTIDADE_DE_ENCONTROS', mensagem: 'Minicurso deve ter entre 2 e 5 encontros' });
234:     }
235:   }
236: 
237:   // R8: ENCONTRO_INVALIDO (se encontros alterados)
238:   if (novosEncontros) {
239:     for (const e of novosEncontros) {
240:       if (new Date(e.inicio) >= new Date(e.fim)) {
241:         return res.status(422).json({ erro: 'ENCONTRO_INVALIDO', mensagem: 'Início deve ser menor que fim' });
242:       }
243:       const duracao = (new Date(e.fim) - new Date(e.inicio)) / 3600000;
244:       if (duracao <= 0 || duracao > 4) {
245:         return res.status(422).json({ erro: 'ENCONTRO_INVALIDO', mensagem: 'Duração fora do permitido' });
246:       }
247:       const dataInicio = e.inicio.split('T')[0];
248:       const dataFim = e.fim.split('T')[0];
249:       if (dataInicio !== dataFim) {
250:         return res.status(422).json({ erro: 'ENCONTRO_INVALIDO', mensagem: 'Encontro deve começar e terminar no mesmo dia' });
251:       }
252:       const dtInicio = new Date(e.inicio);
253:       const dtFim = new Date(e.fim);
254:       if (dtInicio < new Date('2026-10-19T00:00:00-03:00') || dtFim > new Date('2026-10-23T23:59:59-03:00')) {
255:         return res.status(422).json({ erro: 'ENCONTRO_INVALIDO', mensagem: 'Encontro fora do período do evento' });
256:       }
257:       for (let i = 0; i < novosEncontros.length; i++) {
258:         for (let j = 0; j < novosEncontros.length; j++) {
259:           if (i === j) continue;
260:           if (new Date(novosEncontros[i].inicio).getTime() < new Date(novosEncontros[j].fim).getTime() &&
261:               new Date(novosEncontros[i].fim).getTime() > new Date(novosEncontros[j].inicio).getTime()) {
262:             return res.status(422).json({ erro: 'ENCONTRO_INVALIDO', mensagem: 'Encontros da mesma atividade não podem se sobrepor' });
263:           }
264:         }
265:       }
266:     }
267:   }
268: 
269:   // R9: VAGAS_ACIMA_DA_CAPACIDADE (se vagas sendo alteradas)
270:   if (novasVagas !== undefined) {
271:     const sala = salas.find(s => s.id === (novaSalaId || atv.salaId));
272:     if (sala && (novasVagas > sala.capacidade || novasVagas < 1)) {
273:       return res.status(422).json({ erro: 'VAGAS_ACIMA_DA_CAPACIDADE', mensagem: 'Vagas fora do permitido' });
274:     }
275:   }
276: 
277:   // R10: VAGAS_ABAIXO_DOS_INSCRITOS (se vagas sendo alteradas)
278:   if (novasVagas !== undefined && novasVagas < atv.ocupadas) {
279:     return res.status(409).json({ erro: 'VAGAS_ABAIXO_DOS_INSCRITOS', mensagem: 'Vagas não pode ser menor que o número de inscritos' });
280:   }
281: 
282:   // R11: CONFLITO_DE_SALA (se salaId ou encontros alterados)
283:   const salaAlvo = novaSalaId || atv.salaId;
284:   const encontrosAlvo = novosEncontros || atv.encontros;
285:   for (const e of encontrosAlvo) {
286:     for (const atvAtiva of atividades) {
287:       if (atvAtiva.id === atv.id) continue;
288:       if (atvAtiva.salaId !== salaAlvo) continue;
289:       if (calcularSituacao(atvAtiva) === 'cancelada') continue;
290:       for (const ee of atvAtiva.encontros) {
291:         if (new Date(e.inicio).getTime() < new Date(ee.fim).getTime() &&
292:             new Date(e.fim).getTime() > new Date(ee.inicio).getTime()) {
293:           return res.status(409).json({ erro: 'CONFLITO_DE_SALA', mensagem: 'Conflito de sala: sobreposicao de horarios' });
294:         }
295:       }
296:     }
297:   }
298: 
299:   // Aplicar alterações
300:   for (const [key, value] of Object.entries(req.body)) {
301:     if (['titulo', 'vagas'].includes(key)) {
302:       atv[key] = value;
303:     }
304:     if (key === 'salaId') {
305:       atv.salaId = value;
306:     }
307:     if (key === 'encontros') {
308:       atv.encontros = value.map(enc => ({
309:         id: `enc_${String(Math.floor(Math.random() * 0xFFFFFFFF)).toString(16).padStart(8, '0')}`,
310:         inicio: enc.inicio,
311:         fim: enc.fim
312:       }));
313:     }
314:   }
315: 
316:   // Atualizar carga horária
317:   atv.cargaHorariaMinutos = atv.encontros.reduce((acc, e) => acc + (new Date(e.fim) - new Date(e.inicio)) / 60000, 0);
318: 
319:   res.json(atividadeResponse(atv));
320: });
