323: 
324: app.post('/atividades/:id/cancelamento', (req, res) => {
325:   const { "x-usuario": usuario } = req.headers;
326:   if (!usuario) return res.status(401).json({ erro: 'USUARIO_DESCONHECIDO', mensagem: 'Usuário não informado' });
