330: 
331:   // R12: ATIVIDADE_JA_INICIADA
332:   if (calcularSituacao(atv) === 'em_andamento' || calcularSituacao(atv) === 'encerrada') {
333:     return res.status(422).json({ erro: 'ATIVIDADE_JA_INICIADA', mensagem: 'Atividade já foi iniciada' });
334:   }
335: 
336:   // R13: ATIVIDADE_CANCELADA
337:   if (calcularSituacao(atv) === 'cancelada') {
338:     return res.status(422).json({ erro: 'ATIVIDADE_CANCELADA', mensagem: 'Atividade já está cancelada' });
339:   }
340: 
341:   atv._cancelada = true;
342:   res.json(atividadeResponse(atv));
343: });
