const API_BASE = import.meta.env.VITE_API_URL || 'http://localhost:3000';
const DEFAULT_USER = 'org-ana';

async function request(method, path, body = null, usuario = DEFAULT_USER) {
  const headers = { 'Content-Type': 'application/json' };
  if (usuario) headers['X-Usuario'] = usuario;

  const options = { method, headers };
  if (body !== null) {
    options.body = JSON.stringify(body);
  }

  const response = await fetch(`${API_BASE}${path}`, options);
  const data = await response.json();

  if (!response.ok) {
    const error = new Error(data.mensagem || 'Erro desconhecido');
    error.code = data.erro;
    error.status = response.status;
    throw error;
  }

  return data;
}

export const apiService = {
  getSalas: () => request('GET', '/salas'),

  getAtividades: (filtros = {}) => {
    const params = new URLSearchParams();
    if (filtros.dia) params.set('dia', filtros.dia);
    if (filtros.tipo) params.set('tipo', filtros.tipo);
    const queryString = params.toString();
    return request('GET', `/atividades${queryString ? '?' + queryString : ''}`);
  },

  getAtividadeById: (id) => request('GET', `/atividades/${id}`),

  criarAtividade: (data) => request('POST', '/atividades', data),

  atualizarAtividade: (id, data) => request('PATCH', `/atividades/${id}`, data),

  cancelarAtividade: (id) => request('POST', `/atividades/${id}/cancelamento`),
};

import { useState, useEffect, useCallback } from 'react';
import { apiService } from '../services/api';

export function useAtividades() {
  const [atividades, setAtividades] = useState([]);
  const [salas, setSalas] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const carregarAtividades = useCallback(async (filtros = {}) => {
    try {
      setError(null);
      setLoading(true);
      const data = await apiService.getAtividades(filtros);
      setAtividades(data);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }, []);

  const carregarSalas = useCallback(async () => {
    try {
      const data = await apiService.getSalas();
      setSalas(data);
    } catch (err) {
      setError(err.message);
    }
  }, []);

  useEffect(() => {
    carregarAtividades();
    carregarSalas();
  }, [carregarAtividades, carregarSalas]);

  const criar = async (dados) => {
    const result = await apiService.criarAtividade(dados);
    await carregarAtividades();
    return result;
  };

  const atualizar = async (id, dados) => {
    const result = await apiService.atualizarAtividade(id, dados);
    await carregarAtividades();
    return result;
  };

  const cancelar = async (id) => {
    const result = await apiService.cancelarAtividade(id);
    await carregarAtividades();
    return result;
  };

  return {
    atividades,
    salas,
    loading,
    error,
    criar,
    atualizar,
    cancelar,
    recarregar: () => carregarAtividades(),
  };
}

export function formatarDataISO(dataStr) {
  const d = new Date(dataStr);
  return d.toLocaleDateString('pt-BR', {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  });
}

export function formatarHoraISO(dataStr) {
  const d = new Date(dataStr);
  return d.toLocaleTimeString('pt-BR', {
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  });
}

export function formatarDateTime(dataStr) {
  const d = new Date(dataStr);
  return `${formatarDataISO(dataStr)} ${formatarHoraISO(dataStr)}`;
}

export function obterDataISO(dataStr) {
  return new Date(dataStr).toISOString().split('T')[0];
}

export function agruparPorData(atividades) {
  const grupos = {};
  atividades.forEach((atv) => {
    const datas = new Set();
    atv.encontros.forEach((e) => {
      datas.add(obterDataISO(e.inicio));
    });
    datas.forEach((data) => {
      if (!grupos[data]) grupos[data] = [];
      grupos[data].push(atv);
    });
  });

  const datasOrdenadas = Object.keys(grupos).sort();
  const resultado = {};
  datasOrdenadas.forEach((data) => {
    resultado[data] = grupos[data];
  });
  return resultado;
}

export function formatarDuracao(minutos) {
  const horas = Math.floor(minutos / 60);
  const mins = minutos % 60;
  if (horas > 0 && mins > 0) return `${horas}h ${mins}min`;
  if (horas > 0) return `${horas}h`;
  return `${mins}min`;
}

export function getSituacaoLabel(situacao) {
  const labels = {
    prevista: 'Prevista',
    em_andamento: 'Em andamento',
    encerrada: 'Encerrada',
    cancelada: 'Cancelada',
  };
  return labels[situacao] || situacao;
}

export function getTipoLabel(tipo) {
  if (tipo === 'palestra') return 'Palestra';
  if (tipo === 'minicurso') return 'Minicurso';
  return tipo;
}

export function getSituacaoClass(situacao) {
  const classes = {
